{
  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PUSHBACK",
      "evidence": "Require **AUD 6m / 25%**."
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "Require **AUD 5,000 de minimis; AUD 50,000 aggregate tipping basket**, with recovery from the first dollar once exceeded."
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PUSHBACK",
      "evidence": "Restore **24 months after Completion**."
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Separate regime: **100% cap; at least six years; outside general basket, de minimis and buyer-knowledge exclusions**."
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "Expressly carve out **fraud, wilful concealment and deliberate misconduct** from all caps, baskets, time limits, exclusive remedies and non-reliance"
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "**Reject general deemed disclosure.**"
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "**Delete cl 8.3’s blanket buyer/adviser knowledge exclusion**, particularly its extension to matters merely “discoverable”."
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "**Require effective consent and evidence that its conditions are satisfied before Completion.**"
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "Do not accept an unsecured promise of a post-Completion release."
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "Require a **specific line item or an effective Seller-funded arrangement**, including applicable triggered on-costs."
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "Broaden the indemnity to address the relevant ownership/transfer exposure and resulting losses, rather than only the identified payment."
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "Require preservation of logs and other evidence, a documented investigation, current scope/access findings, assessment of applicable obligations and regular updates."
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PARTIAL",
      "evidence": "The **AUD 330,000 aggregate** may be ordinary-course expenditure, but the supplied facts do not establish that conclusion."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "Delete the default that general limitations apply to all Claims."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "Require independent title, ownership, encumbrance and authority evidence, reconciled with the register, together with appropriate transfer and release documentation."
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "Reject the assertion that these positions are settled under the general regime."
    }
  ],
  "adopts_framing": false,
  "adopts_framing_evidence": "",
  "names_manipulation": false
}

